import{_ as e,o as i,c as n,a2 as o}from"./chunks/framework.CgxQ0r6v.js";const p=JSON.parse('{"title":"Planificación Académica: Proyecto Sociotecnológico IV (Trimestre XII)","description":"","frontmatter":{},"headers":[],"relativePath":"materias/Proyecto_Sociotecnologico_IV/Planificacion_Trimestre_IV-XII.md","filePath":"materias/Proyecto_Sociotecnologico_IV/Planificacion_Trimestre_IV-XII.md"}'),r={name:"materias/Proyecto_Sociotecnologico_IV/Planificacion_Trimestre_IV-XII.md"};function t(l,a,c,d,s,u){return i(),n("div",null,[...a[0]||(a[0]=[o('<h1 id="planificacion-academica-proyecto-sociotecnologico-iv-trimestre-xii" tabindex="-1">Planificación Académica: Proyecto Sociotecnológico IV (Trimestre XII) <a class="header-anchor" href="#planificacion-academica-proyecto-sociotecnologico-iv-trimestre-xii" aria-label="Permalink to &quot;Planificación Académica: Proyecto Sociotecnológico IV (Trimestre XII)&quot;">​</a></h1><p>El Trimestre XII es el último trimestre de la carrera, donde los estudiantes completan el ciclo de vida de su solución sociotecnológica, ejecutan la implantación institucional, validan las pruebas de aseguramiento de calidad, entregan los manuales técnicos y defienden su <strong>Trabajo Especial de Grado para optar al título de Ingeniero/a en Informática</strong>.</p><hr><h2 id="📅-trimestre-xii-implantacion-pruebas-optimizacion-e-informe-de-grado-final-unidades-6-7-y-8" tabindex="-1">📅 Trimestre XII: Implantación, Pruebas, Optimización e Informe de Grado Final (Unidades 6, 7 y 8) <a class="header-anchor" href="#📅-trimestre-xii-implantacion-pruebas-optimizacion-e-informe-de-grado-final-unidades-6-7-y-8" aria-label="Permalink to &quot;📅 Trimestre XII: Implantación, Pruebas, Optimización e Informe de Grado Final (Unidades 6, 7 y 8)&quot;">​</a></h2><h3 id="📝-evaluacion-1-evaluacion-pruebas-y-optimizacion-de-alto-nivel-unidad-7" tabindex="-1">📝 Evaluación 1: Evaluación, Pruebas y Optimización de Alto Nivel (Unidad 7) <a class="header-anchor" href="#📝-evaluacion-1-evaluacion-pruebas-y-optimizacion-de-alto-nivel-unidad-7" aria-label="Permalink to &quot;📝 Evaluación 1: Evaluación, Pruebas y Optimización de Alto Nivel (Unidad 7)&quot;">​</a></h3><p><strong>Objetivo:</strong> Aplicar pruebas integrales de calidad de software y hardware, evaluando el cumplimiento de los indicadores establecidos.</p><ul><li>Establecimiento de los indicadores de evaluación y métricas de desempeño del sistema (ISO/IEC 25010).</li><li>Pruebas de estrés, carga, seguridad (análisis de vulnerabilidades) y pruebas funcionales de aceptación (UAT).</li><li>Detección, diagnóstico y corrección de errores críticos y cuellos de botella de rendimiento.</li><li>Plan de optimización y afinamiento de consultas de base de datos e interfaces.</li><li><strong>Actividad:</strong> <strong>Informe de Auditoría de Calidad, Pruebas y Optimización.</strong> (25%)</li></ul><h3 id="📝-evaluacion-2-estrategia-de-implantacion-y-evaluacion-comunitaria-unidad-6" tabindex="-1">📝 Evaluación 2: Estrategia de Implantación y Evaluación Comunitaria (Unidad 6) <a class="header-anchor" href="#📝-evaluacion-2-estrategia-de-implantacion-y-evaluacion-comunitaria-unidad-6" aria-label="Permalink to &quot;📝 Evaluación 2: Estrategia de Implantación y Evaluación Comunitaria (Unidad 6)&quot;">​</a></h3><p><strong>Objetivo:</strong> Poner en producción la solución en la organización y evaluar su impacto y adopción operativa.</p><ul><li>Ejecución del plan de implantación (despliegue en servidores de producción, configuración de dominio, SSL y seguridad).</li><li>Migración y verificación de datos reales.</li><li>Evaluación del impacto sociotecnológico en los procesos de la institución u organización.</li><li>Acta formal de instalación y entrega definitiva del sistema.</li><li><strong>Actividad:</strong> <strong>Informe de Implantación y Evaluación de Impacto Operativo.</strong> (25%)</li></ul><h3 id="📝-evaluacion-3-manuales-de-usuario-sistema-y-plan-de-entrenamiento-unidad-8" tabindex="-1">📝 Evaluación 3: Manuales de Usuario, Sistema y Plan de Entrenamiento (Unidad 8) <a class="header-anchor" href="#📝-evaluacion-3-manuales-de-usuario-sistema-y-plan-de-entrenamiento-unidad-8" aria-label="Permalink to &quot;📝 Evaluación 3: Manuales de Usuario, Sistema y Plan de Entrenamiento (Unidad 8)&quot;">​</a></h3><p><strong>Objetivo:</strong> Elaborar la documentación de nivel profesional y ejecutar el entrenamiento integral a usuarios y administradores.</p><ul><li>Manual de Usuario: guía interactiva o ilustrada para usuarios finales.</li><li>Manual del Sistema y de Administración Técnica: arquitectura, despliegue, APIs, políticas de respaldo y seguridad, licenciamiento libre (GPL v3 o compatible).</li><li>Ejecución del plan de capacitación y transferencia tecnológica formal.</li><li><strong>Actividad:</strong> <strong>Entrega de Manuales Técnicos y Constancias de Entrenamiento.</strong> (25%)</li></ul><h3 id="📝-evaluacion-4-presentacion-y-defensa-del-trabajo-especial-de-grado-unidad-8" tabindex="-1">📝 Evaluación 4: Presentación y Defensa del Trabajo Especial de Grado (Unidad 8) <a class="header-anchor" href="#📝-evaluacion-4-presentacion-y-defensa-del-trabajo-especial-de-grado-unidad-8" aria-label="Permalink to &quot;📝 Evaluación 4: Presentación y Defensa del Trabajo Especial de Grado (Unidad 8)&quot;">​</a></h3><p><strong>Objetivo:</strong> Defender públicamente el proyecto sociotecnológico ante el jurado calificador y la comunidad, demostrando competencias de ingeniería.</p><ul><li>Estructura formal del Informe Final de Proyecto según la normativa de Trabajos Especiales de Grado de la UPTT.</li><li>Portafolio de Evidencias: acreditación completa de horas comunitarias, cartas de aceptación y avales de satisfacción institucional.</li><li>Demostración integral en vivo del sistema en funcionamiento real ante el jurado examinador.</li><li>Defensa pública, deliberación del jurado y lectura del acta de grado.</li><li><strong>Actividad:</strong> <strong>Defensa Pública del Trabajo Especial de Grado e Informe Empastado.</strong> (25%)</li></ul><hr><h2 id="✅-resumen-del-trimestre" tabindex="-1">✅ Resumen del Trimestre <a class="header-anchor" href="#✅-resumen-del-trimestre" aria-label="Permalink to &quot;✅ Resumen del Trimestre&quot;">​</a></h2><p>Con la aprobación de este trimestre, los estudiantes culminan exitosamente el Programa Nacional de Formación en Informática (PNFI), habiendo demostrado la capacidad de liderar, diseñar, construir e implantar soluciones sociotecnológicas de alto impacto para el desarrollo soberano de la nación.</p>',19)])])}const g=e(r,[["render",t]]);export{p as __pageData,g as default};
